import fs from 'fs';
import path from 'path';

const srcDir = 'src';

// Find all JS files
function findJsFiles(dir) {
  const files = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...findJsFiles(full));
    } else if (entry.name.endsWith('.js')) {
      files.push(full);
    }
  }
  return files;
}

const files = findJsFiles(srcDir);

// Extract exported function names
const funcNames = new Set();
for (const file of files) {
  const content = fs.readFileSync(file, 'utf-8');
  const exportMatches = content.matchAll(/export\s+function\s+(\w+)/g);
  for (const m of exportMatches) {
    funcNames.add(m[1]);
  }
  // Also non-exported
  const localMatches = content.matchAll(/(?<!export\s)function\s+(\w+)/g);
  for (const m of localMatches) {
    funcNames.add(m[1]);
  }
}

// Count real call sites (not in comments)
const counts = {};
for (const name of funcNames) {
  counts[name] = 0;
}

for (const file of files) {
  const content = fs.readFileSync(file, 'utf-8');
  const lines = content.split('\n');
  for (const line of lines) {
    // Skip comment lines
    const trimmed = line.trim();
    if (trimmed.startsWith('//') || trimmed.startsWith('*') || trimmed.startsWith('/*')) continue;

    // For each function, count calls in this line
    for (const name of funcNames) {
      // Match name followed by '(' but not preceded by 'function ' or 'export function '
      const regex = new RegExp(`\\b${name}\\s*\\(`, 'g');
      const matches = line.match(regex);
      if (matches) {
        // Make sure it's not a definition
        if (!line.includes(`function ${name}(`) && !line.includes(`export function ${name}(`)) {
          counts[name] += matches.length;
        }
      }
    }
  }
}

// Sort by count
