const fs = require('fs');
const path = require('path');

const configsDir = path.join(__dirname, 'configs');

function findJsonFiles(dir) {
  const files = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...findJsonFiles(fullPath));
    } else if (entry.name.endsWith('.json')) {
      files.push(fullPath);
    }
  }
  return files;
}

function migrateFile(filePath) {
  const raw = fs.readFileSync(filePath, 'utf-8');
  const data = JSON.parse(raw);

  if (data.version === 2) {
    console.log(`Skipping (already v2): ${filePath}`);
    return;
  }

  if (data.version !== 1) {
    console.log(`Skipping (unknown version ${data.version}): ${filePath}`);
    return;
  }

  const migrated = {};

  for (const [key, value] of Object.entries(data)) {
    if (key === 'version') {
      migrated.version = 2;
    } else if (key === 'timeoutMs') {
      migrated.timeout_s = value / 1000;
    } else if (key === 'retry') {
      migrated.retry = {
        attempts: value.count,
        backoff_s: value.backoffMs / 1000
      };
    } else if (key === 'owners') {
      if (typeof value === 'string') {
        const emails = value
          .split(',')
          .map(s => s.trim().toLowerCase())
          .filter(s => s.length > 0);
        migrated.owners = emails;
      } else {
        migrated.owners = value;
      }
    } else {
      migrated[key] = value;
    }
  }

  if (!('retry' in data)) {
    migrated.retry = { attempts: 0, backoff_s: 0 };
  }

  fs.writeFileSync(filePath, JSON.stringify(migrated, null, 2) + '\n', 'utf-8');
  console.log(`Migrated: ${filePath}`);
}

const files = findJsonFiles(configsDir).sort();
for (const file of files) {
  migrateFile(file);
}
